#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long maximumSumOfHeights(vector<int>& maxHeights){int n=maxHeights.size();long long ans=0;for(int p=0;p<n;++p){long long sum=maxHeights[p],h=maxHeights[p];for(int i=p-1;i>=0;--i){h=min(h,(long long)maxHeights[i]);sum+=h;}h=maxHeights[p];for(int i=p+1;i<n;++i){h=min(h,(long long)maxHeights[i]);sum+=h;}ans=max(ans,sum);}return ans;}};
